import { z } from 'zod';

/**
 * ONBOARDING-UX-01. URL names (slugs) are generated by the server from the submitted name; nobody has to build a technical
 * identifier by hand. One definition shared by the API and the web app.
 *
 * Canonical form: lowercase letters and digits in groups separated by SINGLE hyphens, no leading or trailing hyphen,
 * 2 to 60 characters. This applies to NEW explicit input and to generated values only: `slugSchema` (common.ts) stays the
 * lenient rule so every existing business and branch slug keeps working, and an established URL is never rewritten.
 */
export const SLUG_MIN_LENGTH = 2;
export const SLUG_MAX_LENGTH = 60;
/** Room left for a "-NN" uniqueness suffix. */
export const SLUG_BASE_MAX_LENGTH = 50;
const CANONICAL_SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

/** Names that would collide with application routes or look like official paths. Checked for generated and explicit slugs. */
export const RESERVED_SLUGS: ReadonlySet<string> = new Set([
  'admin', 'api', 'app', 'auth', 'cashier', 'dashboard', 'feedback', 'login', 'logout', 'loyalty', 'new', 'null',
  'platform', 'privacy', 'settings', 'signup', 'support', 'terms', 'undefined', 'www',
]);

export const canonicalSlugSchema = z
  .string()
  .trim()
  .toLowerCase()
  .min(SLUG_MIN_LENGTH)
  .max(SLUG_MAX_LENGTH)
  .regex(CANONICAL_SLUG, {
    error: 'URL name may only contain lowercase letters and numbers, separated by single hyphens.',
  })
  .refine((value) => !RESERVED_SLUGS.has(value), { error: 'This URL name is reserved. Choose another.' });

export function isCanonicalSlug(value: string): boolean {
  return (
    value.length >= SLUG_MIN_LENGTH &&
    value.length <= SLUG_MAX_LENGTH &&
    CANONICAL_SLUG.test(value) &&
    !RESERVED_SLUGS.has(value)
  );
}

/**
 * Deterministic base slug from a display name: accents are removed, "&" reads as "and", everything else that is not a
 * letter or digit becomes one hyphen. A name with no Latin letters or digits (for example Arabic only) has nothing to
 * derive, so the caller's `fallback` is used and the uniqueness suffix tells businesses apart.
 */
export function slugBaseFromName(name: string, fallback: string): string {
  const folded = name
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/&/g, ' and ');
  let base = folded.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  if (base.length > SLUG_BASE_MAX_LENGTH) base = base.slice(0, SLUG_BASE_MAX_LENGTH).replace(/-+$/g, '');
  if (base.length < SLUG_MIN_LENGTH) base = fallback;
  return base;
}

/**
 * The n-th candidate for a base: n = 1 is the base itself, n >= 2 is "base-n". Always canonical and at most 60
 * characters. Reserved results are skipped by returning null so the allocator moves to the next number.
 */
export function slugCandidate(base: string, attempt: number): string | null {
  const suffix = attempt <= 1 ? '' : `-${attempt}`;
  const candidate = `${base.slice(0, SLUG_MAX_LENGTH - suffix.length).replace(/-+$/g, '')}${suffix}`;
  return isCanonicalSlug(candidate) ? candidate : null;
}
